def _git(folder, *a):
    "The output of `git` run in `folder`; None when git is missing or `folder` is not a repo."
    try: r = subprocess.run(['git', '-C', str(folder), *a], capture_output=True, text=True)
    except OSError: return None
    return r.stdout if r.returncode == 0 else None

def checked_changes(t, since):
    "The `changes` of thread `t`, each marked `(not in git)` when no commit or file of the worker's repos since `since` matches it; no repo, no marks."
    since = f'--since={int(since)}'
    logs = [(_git(f, 'log', '--all', since, '--format=%H'), _git(f, 'log', '--all', since, '--name-only', '--format=')) for f in t['folders']]
    logs = [l for l in logs if None not in l]
    shas = '\n'.join(h for h, _ in logs).split()
    files = [l for _, n in logs for l in n.split('\n') if l]
    seen = lambda c: any(s.startswith(c) for s in shas) if re.fullmatch(r'[0-9a-f]{7,40}', c) else any(f == c or f.endswith('/' + c) or c.endswith('/' + f) for f in files)
    return [c if not logs or seen(c) else f'{c} (not in git)' for c in t['changes']]

# %% ../nbs/26_peer_report.ipynb #4400ac5b
FLAGGED = re.compile(r'xfail|pytest\.mark\.skip|\bskip\(|#\s*noqa|type:\s*ignore')

def diff_flags(folder, since):
    "The lines that commits of `folder` since `since` and its working tree add, which switch a check off: `{file, line}` for each. None outside git."
    out = []
    for diff in (_git(folder, 'log', '--all', f'--since={int(since)}', '-p', '-U0', '--format='), _git(folder, 'diff', 'HEAD', '-U0')):
        file = ''
        for l in (diff or '').splitlines():
            if l.startswith('+++ '): file = l.removeprefix('+++ ').removeprefix('b/')
            elif l.startswith('+') and FLAGGED.search(l): out.append(dict(file=file, line=l[1:].strip()))
    return out

def proof_reviewer(t):
    "The flag for thread `t` when it has proof and no item of it names a reviewer, else ''."
    return 'no reviewer in the proof' if t['proof'] and not any(re.search('review', p, re.I) for p in t['proof']) else ''

# %% ../nbs/26_peer_report.ipynb #65f5028e
COLS = ('Asked by', 'Done by', 'What', 'Changed', 'Proof', 'Replies', 'State')

def _cell(s, n=80):
    "`s` made safe for one table cell."
    s = ' '.join(str(s).split()).replace('|', '\\|')
    return s if len(s) <= n else s[:n - 1] + '…'

def table(ts):
    "A Markdown table of the threads `ts`, one row each."
    row = lambda *c: '| ' + ' | '.join(c) + ' |'
    return '\n'.join([row(*COLS), row(*['---']*len(COLS)),
                      *(row(*map(_cell, (t['asker'], t['worker'] or '-', t['ask'], '; '.join(t['changes']) or '-', '; '.join(t['proof']) or '-', t['replies'], t['state']))) for t in ts)])

# %% ../nbs/26_peer_report.ipynb #d3be5945
GLOSSARY = {
    'peer': 'Another session on this Mac: Claude Code, Codex or Ramabana.',
    'note': 'A message that needs no answer.',
    'ask': 'A message that asks a peer to do work.',
    'reply': 'The answer to an ask.',
    'thread': 'One ask and all the replies to it.',
    'hop': f'One message in a thread. A thread carries at most {HOP_MAX} messages: the ask and {HOP_MAX - 1} replies.',
    'work together mode': 'A time when peers may take asks from each other with no one at the keyboard.',
    'proof': 'A test or a check that shows the work is done.',
    'budget': f"The most that one session may do: {PEER_BUDGET['messages']} messages sent in {TOGETHER_HOURS} hours, and in work together mode {PEER_BUDGET['messages']} messages sent and {PEER_BUDGET['turns']} asks taken.",
}

def glossary(text):
    "The lines of `GLOSSARY` for the terms that `text` uses."
    return '\n'.join(f'- **{k}**: {v}' for k, v in GLOSSARY.items() if re.search(rf'\b{re.escape(k)}s?\b', text, re.I))

# %% ../nbs/26_peer_report.ipynb #65a81760
TODO = {'waiting': 'Get an answer to', 'not proven': 'Ask for proof of', 'refused': 'Look at the refusal of', 'failed': 'Re-send or drop', 'stopped': 'Restart'}

def derived_actions(ts):
    "The action lines that the table alone shows: each one is `what to do: where`."
    where = lambda t: (t['worker'] or t['asker']) + (f" ({Path(t['folders'][0]).name})" if t['folders'] else '')
    return [f"- {TODO[t['state']]} '{_cell(t['ask'], 40)}'" + (f" ({t['why']})" if t['why'] else '') + f": {where(t)}" for t in ts if t['state'] in TODO]

SUMMARY_SP = """You write the morning report for a user who was away. Use simple technical English (ASD-STE100), grade 9 reading level.
You get a list of threads. Answer in two parts. First a line `EXAMPLES`, then one bullet for each change, one short sentence each.
Then a line `ACTIONS`, then one bullet for each extra thing the user must do, written as "what to do: where".
Always name a waiting ask, a thread with no proof and a stopped thread as an action. Write no other text."""

def _bullets(s): return [l if l.lstrip().startswith(('-', '*')) else f'- {l}' for l in map(str.strip, s.splitlines()) if l]

def summarise(ts, agent=None):
    "The simple examples and the action list for threads `ts`, from one `summary` model call."
    from ramabana.agent import mk_agent
    agent = agent or mk_agent()[0]   # `mk_agent` gives `(agent, host)`
    out = agent.oneshot('\n'.join(f"- {t['asker']} asked {t['worker'] or 'nobody'}: {t['ask']} (state: {t['state']}; changed: {'; '.join(t['changes']) or 'nothing'})" for t in ts), SUMMARY_SP, job='summary')
    ex, *ac = re.split(r'(?im)^\s*actions\s*:?\s*$', out or '', maxsplit=1) + ['']
    return '\n'.join(_bullets(re.sub(r'(?im)^\s*examples\s*:?\s*$', '', ex))), '\n'.join(_bullets(ac[0]))

# %% ../nbs/26_peer_report.ipynb #7e247bda
MISSING = 'The summary model failed'

def _changes(ts):
    "One line for each thread in `ts`, from the `changes` and `proof` of its replies."
    return '\n'.join(f"- {t['worker'] or '-'} for {t['asker']}: {_cell('; '.join(t['changes']) or 'no change', 200)} (proof: {_cell('; '.join(t['proof']) or 'none', 200)})" for t in ts)

MODEL_MARK = '_The examples come from the summary model._'

def claude_projects():
    "The folder of Claude Code's projects: `projects` in `$CLAUDE_CONFIG_DIR`, else in `~/.claude`."
    return Path(os.environ.get('CLAUDE_CONFIG_DIR') or '~/.claude').expanduser()/'projects'

def _first_user(p, cut=120):
    "The text of the first user line in the run file `p`, cut short; it reads no more of the file."
    with open(p, errors='replace') as f:
        for l in f:
            try: r = json.loads(l)
            except ValueError: continue
            m = r.get('message') if isinstance(r, dict) and isinstance(r.get('message'), dict) else {}
            if isinstance(r, dict) and (r.get('type') == 'user' or m.get('role') == 'user'):
                c = m.get('content', '')
                if isinstance(c, list): c = ' '.join(b.get('text', '') for b in c if isinstance(b, dict))
                return ' '.join(str(c).split())[:cut]
    return ''

def subagent_runs(since, root=None):
    "The subagent runs of the user's own Claude Code sessions changed since `since`, oldest first: `{first, at, size, path}`. Only the first user line, the mtime and the size of each run file are read; none when the folder is missing."
    root = Path(root or claude_projects())
    files = [*root.glob('*/subagents/*.jsonl'), *root.glob('*/*/subagents/*.jsonl')] if root.is_dir() else []
    runs = [dict(first=_first_user(p), at=s.st_mtime, size=s.st_size, path=str(p)) for p in files if (s := p.stat()).st_mtime > since]
    return sorted(runs, key=lambda r: r['at'])

def _runs_table(runs):
    "A Markdown table of the subagent `runs`."
    return '\n'.join(['| When | Size | First line |', '| --- | --- | --- |', *(f"| {datetime.fromtimestamp(r['at']):%a %H:%M} | {r['size'] // 1024} KB | {_cell(r['first'])} |" for r in runs)])

def _flags_table(flags):
    "A Markdown table of the diff `flags`: `{repo, file, line}`."
    return '\n'.join(['| Repo | File | Added line |', '| --- | --- | --- |', *(f"| {_cell(f['repo'])} | {_cell(f['file'])} | {_cell(f['line'])} |" for f in flags)])

def _reviews(ts):
    "The action lines for the threads of `ts` whose proof names no reviewer."
    return [f"- Ask a session that did not write it to review '{_cell(t['ask'], 40)}': {t['worker'] or t['asker']}" for t in ts if proof_reviewer(t)]

def report(since, cfg=None, agent=None, summary=None, model=False, sessions=None):
    "The Markdown report of the log since time `since`. It calls no model unless `model` is true or `summary` (a function like `summarise`) is given; the examples then come from the replies. `sessions` lists the user's own subagent runs (default: `subagent_runs`)."
    d = peers_dir(cfg)
    known = {r['key']: r for r in registered(d)} | {r['from']['key']: r['from'] for r in read_log(d) if r.get('from', {}).get('key')}
    ts = [t | dict(changes=checked_changes(t, since)) for t in threads(read_log(d, since), known, read_log(d))]
    ex, ac, why, use = '', '', 'it gave no answer', bool(ts) and (model or summary is not None)
    if not ts: ex = 'No thread in this time.'
    elif use:
        try: ex, ac = (summary or summarise)(ts, agent)
        except Exception as e: why = f'{type(e).__name__}: {e}'
    acts = '\n'.join(dict.fromkeys([*derived_actions(ts), *_reviews(ts), *_bullets(ac)])) or 'Nothing to do.'
    if not ex: ex = _changes(ts) + (f"\n\n{MISSING}: {why}. The lines above come from the replies." if use else '')
    elif use: ex += f'\n\n{MODEL_MARK}'
    flags = [f | dict(repo=Path(fo).name) for fo in dict.fromkeys(fo for t in ts for fo in t['folders']) for f in diff_flags(fo, since)]
    runs = subagent_runs(since) if sessions is None else sessions
    body = f"{table(ts)}\n\n## What changed\n\n{ex}\n\n## Your actions\n\n{acts}"
    if flags: body += f"\n\n## Checks switched off in the diff\n\n{_flags_table(flags)}"
    if runs: body += f"\n\n## Your own subagent runs\n\n{_runs_table(runs)}"
    return f"# Night of {datetime.fromtimestamp(since):%Y-%m-%d}\n\n{body}\n\n## Glossary\n\n{glossary(body)}\n"

# %% ../nbs/26_peer_report.ipynb #2f316937
def report_path(since, cfg=None):
    "The file in the reports folder for the report since `since`."
    return peers_dir(cfg)/'reports'/f'{datetime.fromtimestamp(since):%Y-%m-%d-%H%M}.md'

def save_report(since, cfg=None, summary=None, model=False):
    "Write the report since `since` to the reports folder; a file with examples and newer than the whole log is kept, but with `model` one that the model did not write is made again."
    d, p = peers_dir(cfg), report_path(since, cfg)
    if p.exists() and MISSING not in p.read_text() and (not model or MODEL_MARK in p.read_text()) and not read_log(d, p.stat().st_mtime): return p
    p.parent.mkdir(exist_ok=True)
    p.write_text(report(since, cfg, summary=summary, model=model))
    return p

# %% ../nbs/26_peer_report.ipynb #a5017f48
def _since(s):
    "Time `s` as seconds since 1970: a number or an ISO date."
    try: return float(s)
    except ValueError: return datetime.fromisoformat(s).timestamp()

def report_cli(argv, cfg=None):
    "Run `ramabana report` with the arguments `argv`; the exit code."
    p = argparse.ArgumentParser(prog='ramabana report')
    p.add_argument('--since', help='start time: seconds since 1970 or YYYY-MM-DD[ HH:MM]')
    p.add_argument('--save', action='store_true', help='write the report to the reports folder')
    p.add_argument('--model', action='store_true', help='let the summary model write the examples (default: none, no model call)')
    a = p.parse_args(argv)
    ends = [r['started'] for r in read_log(peers_dir(cfg)) if r.get('event') == 'together_end']
    try: since = _since(a.since) if a.since else ends[-1] if ends else time.time() - TOGETHER_HOURS*3600
    except ValueError: print(f'bad time {a.since!r}', file=sys.stderr); return 2
    print(save_report(since, cfg, model=a.model) if a.save else report(since, cfg, model=a.model))
    return 0

# %% ../nbs/26_peer_report.ipynb #cae4a04b
if __name__ == '__main__': sys.exit(report_cli(sys.argv[1:]))
